1	import { launchBrowser, isLoggedIn } from './browser.js';
2	import { listStores, switchStore } from './stores.js';
3	import { scanStore } from './monitor.js';
4	import { closePopups } from './popups.js';
5	import { loadState, saveState, diffStore } from './state.js';
6	import { sendFeishu } from './feishu.js';
7	import { log } from './logger.js';
8	
9	/** 执行一轮完整监测 */
10	export async function runOnce(cfg) {
11	  const { context, page } = await launchBrowser(cfg);
12	  try {
13	    if (!(await isLoggedIn(page, cfg))) {
14	      throw new Error('未登录。请先运行 `npm run login` 完成一次人工登录。');
15	    }
16	    await closePopups(page);
17	
18	    // 确定店铺清单
19	    let stores = cfg.stores === 'all' && cfg.storeList.length === 0
20	      ? await listStores(page)
21	      : cfg.storeList;
22	    if (!stores || stores.length === 0) {
23	      log.warn('未能获取店铺清单；仅监测当前店铺。可在 config.storeList 手动填写店铺名。');
24	      stores = [null]; // null = 当前店铺，不切换
25	    }
26	
27	    const state = loadState();
28	    state.stores = state.stores || {};
29	    const allEvents = [];
30	    const summaries = [];
31	
32	    for (const store of stores) {
33	      const label = store || '(当前店铺)';
34	      try {
35	        if (store) {
36	          const ok = await switchStore(page, store, cfg);
37	          if (!ok) { log.warn(`切换到「${store}」失败，跳过`); continue; }
38	        }
39	        const result = await scanStore(page, label, cfg);
40	        log.info('扫描结果：', result);
41	        summaries.push(result);
42	
43	        const prev = state.stores[label];
44	        const events = diffStore(prev, result, cfg.alerts);
45	        for (const ev of events) allEvents.push({ store: label, ...ev });
46	
47	        // 更新快照
48	        state.stores[label] = {
49	          onSaleCount: result.onSaleCount,
50	          trafficWatchCount: result.trafficWatchCount,
51	          trafficDeclineCount: result.trafficDeclineCount,
52	          trafficAnomalyTotal: result.trafficAnomalyTotal,
53	          updatedAt: new Date().toISOString(),
54	        };
55	      } catch (e) {
56	        log.error(`店铺「${label}」监测出错：`, e.message);
57	      }
58	    }
59	
