2	
3	/**
4	 * 通用弹窗关闭策略。登录成功后 / 切换店铺时 / 页面加载后会弹出多种不固定的弹窗，
5	 * 需求明确「一律关闭，可能还会有其他类型的弹窗，都关闭」。已知类型包括：
6	 *   - 推广券 / 调价提效 / 店铺提效 / 新功能提示等营销弹窗
7	 *   - 「您有以下待办任务需要尽快处理」待办任务模态框（右上角 X）
8	 *   - 点击「消息」后弹出的「全部消息」通知面板 / 「商品不合规，影响售卖」通知（右上角 X）
9	 * 策略：多轮「文本按钮 + 关闭图标 + Esc」清扫，不依赖单一选择器。
10	 */
11	
12	// 需要点击的按钮文本（精确/包含匹配）。仅放「关闭/忽略」类，绝不放「去处理/去填写」等会跳转的按钮。
13	const DISMISS_TEXTS = [
14	  '稍后再说', '我知道了', '知道了', '暂不领取', '暂不参与',
15	  '以后再说', '下次再说', '不再提示', '暂不处理', '取消', '关闭',
16	];
17	
18	// 关闭图标的候选选择器（Temu / 常见 UI 库）
19	const CLOSE_ICON_SELECTORS = [
20	  '[aria-label="close"]',
21	  '[aria-label="关闭"]',
22	  '.ant-modal-close',
23	  '.ant-drawer-close',
24	  '.ant-notification-notice-close',
25	  '[class*="closeIcon"]',
26	  '[class*="close-icon"]',
27	  '[class*="Close_"]',
28	  '[class*="_close"]',
29	  'svg[class*="close" i]',
30	];
31	
32	// 已知弹窗的标题/关键文本。命中后在其容器内优先点关闭图标（这类弹窗没有「关闭」文本按钮，
33	// 只有右上角 X，且往往带「去处理」等会跳转的按钮，绝不能误点）。
34	const KNOWN_DIALOG_KEYWORDS = [
35	  '待办任务需要尽快处理', // 待办任务模态框
36	  '全部消息',             // 消息通知面板
37	  '商品不合规',           // 违规通知
38	];
39	
40	/**
41	 * 关闭当前页面上所有可见弹窗。多轮尝试直到无可关闭项或达到上限。
42	 * @param {import('playwright').Page} page
43	 */
44	export async function closePopups(page, { rounds = 4 } = {}) {
45	  let totalClosed = 0;
46	  for (let r = 0; r < rounds; r++) {
47	    let closedThisRound = 0;
48	
49	    // 1) 文本按钮
50	    for (const t of DISMISS_TEXTS) {
51	      const btn = page.getByRole('button', { name: t, exact: false }).first();
52	      if (await safeClick(btn)) { closedThisRound++; continue; }
53	      const el = page.getByText(t, { exact: true }).first();
54	      if (await safeClick(el)) closedThisRound++;
