$ProgressPreference='SilentlyContinue'
function Probe($label,$uri,$useProxy){
  $args=@{Uri=$uri;TimeoutSec=15;UseBasicParsing=$true;MaximumRedirection=0;ErrorAction='Stop'}
  if($useProxy){$args.Proxy='http://127.0.0.1:7897'}
  $sw=[Diagnostics.Stopwatch]::StartNew()
  try{ $r=Invoke-WebRequest @args; "{0,-22} OK   HTTP {1}  {2}ms" -f $label,$r.StatusCode,$sw.ElapsedMilliseconds }
  catch{
    $code=$null; if($_.Exception.Response){$code=[int]$_.Exception.Response.StatusCode}
    "{0,-22} FAIL {1}  {2}ms  {3}" -f $label,$code,$sw.ElapsedMilliseconds,($_.Exception.Message -replace '\s+',' ').Substring(0,[Math]::Min(90,($_.Exception.Message -replace '\s+',' ').Length))
  }
}
