import { chromium } from 'playwright';

const PROXY = 'http://127.0.0.1:7897';
const USERDATA = 'E:/project/temu/temu-monitor/.userdata';
const DEEP = 'https://agentseller.temu.com/goods/list';
const ROOT = 'https://agentseller.temu.com/';

async function once(page, url) {
  const t0 = Date.now();
  try {
    const resp = await page.goto(url, { waitUntil: 'commit', timeout: 15000 });
    return `OK  status=${resp && resp.status()}  url=${page.url().slice(0, 50)}  ${Date.now() - t0}ms`;
  } catch (e) {
    return `FAIL ${(e.message || '').split('\n')[0].replace('page.goto: ', '')}  ${Date.now() - t0}ms`;
  }
}

async function block(name, useProxy, steps) {
  const opts = {
    headless: true,
    args: ['--disable-blink-features=AutomationControlled'],
  };
  if (useProxy) opts.proxy = { server: PROXY };
  const ctx = await chromium.launchPersistentContext(USERDATA, opts);
  const page = ctx.pages()[0] || await ctx.newPage();
  console.log(`\n[${name}] proxy=${useProxy}`);
  for (const [label, url] of steps) {
    if (page.isClosed()) { console.log(`  ${label}: (page closed)`); break; }
    console.log(`  ${label}: ${await once(page, url)}`);
    await page.waitForTimeout(1200).catch(() => {});
  }
  await ctx.close().catch(() => {});
}

// 1) 代理是否连得上中立 HTTPS 站点（判断代理本身死没死）
await block('neutral-via-proxy', true, [
  ['example.com', 'https://example.com/'],
  ['cloudflare', 'https://www.cloudflare.com/'],
]);

// 2) 代理下：根页 → 深链（连试两轮）
await block('temu-via-proxy', true, [
  ['root #1', ROOT], ['deep #1', DEEP],
  ['root #2', ROOT], ['deep #2', DEEP],
]);

// 3) 直连（不走代理）：根页 → 深链
await block('temu-direct', false, [
  ['root', ROOT], ['deep', DEEP],
]);

console.log('\nDONE');

